"""Build focused small-pet category pages from existing product records."""
import json,re,html
from pathlib import Path
from sync_product_output import catalog_cards,format_size,format_moq
P=Path(__file__).resolve().parents[1]/'public';E=html.escape
CONFIG=[('rabbit-guinea-pig-cages','Rabbit & Guinea Pig Cages',['rabbit-650-cage','guinea-pig-650-cage'],'Explore the 650 Rabbit Cage and 650 Guinea Pig Cage for wholesale sourcing. Compare product specifications and confirm your color and packaging requirements.','The two 650 models share the listed dimensions, materials, weights and ordering quantities. Select the product name for your range and confirm included accessories and packaging with our team.'),('cat-products','Cat Products',['cat-litter-box-75','cat-feeder-automatic'],'Browse our existing cat litter box and automatic feeder / water dispenser. Review each model for dimensions, materials and ordering requirements.','These are two different product types. Use the individual detail pages to review the specifications and confirm the configuration needed for your order.')]
CONFIG.append(('turtle-tanks','Turtle Tanks',['turtle-tank'],'Explore the existing Turtle Tank from KANAPET. Review its product dimensions, materials and ordering information before requesting a wholesale quote.','This range currently contains one model. Confirm the intended configuration, packaging and any separately ordered accessories with our team.'))
def build():
 ps=json.loads((P/'data/products.json').read_text(encoding='utf-8'));cs=json.loads((P/'data/categories.json').read_text(encoding='utf-8'));by={p['slug']:p for p in ps}
 src=(P/'products.html').read_text(encoding='utf-8');header=re.search(r'<header>.*?</header>',src,re.S)[0];footer=src[src.index('<footer>'):]
 for slug,label,ids,intro,note in CONFIG:
  items=[by[i] for i in ids];url='https://www.kanapet.com/'+slug+'.html';title='Wholesale '+label+' | KANAPET';desc='Explore KANAPET '+label.lower()+'. Review existing models, dimensions, materials and MOQ, then request a wholesale or private-label quote.'
  schema={'@context':'https://schema.org','@type':'CollectionPage','name':label,'url':url,'mainEntity':{'@type':'ItemList','itemListElement':[{'@type':'ListItem','position':i+1,'name':p['name'],'url':'https://www.kanapet.com/product/'+p['slug']+'.html'} for i,p in enumerate(items)]}}
  rows=''.join('<tr><th scope="row"><a href="/product/'+p['slug']+'.html">'+E(p['name'])+'</a></th><td>'+E(format_size(p['size']))+'</td><td>'+E(p['material'])+'</td><td>'+E(format_moq(p['moq']))+'</td></tr>' for p in items)
  page=f"""<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/categories.css"><link rel="icon" href="/favicon.ico"><script type="application/ld+json">{json.dumps(schema)}</script></head><body>{header}<main><section class="page-header"><div class="container"><p class="category-breadcrumb"><a href="products.html">All Products</a> / {E(label)}</p><h1>Wholesale {E(label)}</h1><p>{E(intro)}</p></div></section><section class="section"><div class="container"><h2>Explore the existing range</h2><div class="products-grid">{catalog_cards(items,cs)}</div></div></section><section class="section"><div class="container"><h2>Review model specifications</h2><p>{E(note)}</p><div class="category-table"><table><thead><tr><th scope="col">Product</th><th scope="col">Product dimensions</th><th scope="col">Materials</th><th scope="col">MOQ</th></tr></thead><tbody>{rows}</tbody></table></div><p>Dimensions are product measurements, not carton dimensions. Read the individual product ordering notes for carton quantities and packaging.</p><h2>Prepare your quote request</h2><h3>What information should I send?</h3><p>Include the model, order quantity, preferred colors, packaging and destination market. Confirm any required accessories before ordering.</p><h3>Can I discuss private-label requirements?</h3><p>Send your color, logo and packaging requirements for review. For a new design, see our <a href="oem-odm.html">OEM &amp; ODM services</a>.</p><p><a href="factory.html">Explore our factory</a> · <a href="products.html">Browse all products</a></p><a class="btn btn-primary" href="contact.html">Request a Quote</a></div></section></main>{footer}</body></html>"""
  (P/(slug+'.html')).write_text(page,encoding='utf-8');print(slug,len(items),'products')
if __name__=='__main__':build()
